-- QQ bot binding now requires a one-time code generated by the logged-in user
-- on the website. Bindings created by the old "/绑定 <email>" flow could be made
-- by anyone who knew the email, so they are all dropped and users rebind.
DELETE FROM qqbot_bindings;

CREATE TABLE IF NOT EXISTS qqbot_bind_codes (
    id BIGSERIAL PRIMARY KEY,
    app_id VARCHAR(64) NOT NULL,
    user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    code_hash CHAR(64) NOT NULL, -- sha256(app_id + code), hex; the code itself is never stored
    expires_at TIMESTAMPTZ NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    CONSTRAINT qqbot_bind_codes_hash_unique UNIQUE (code_hash)
);

CREATE INDEX IF NOT EXISTS idx_qqbot_bind_codes_user ON qqbot_bind_codes (user_id);
